mapper.select:
SELECT *
FROM lunaerp_business_export_doc_item
WHERE doc_id = #{docId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE lunaerp_business_export_doc_item
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE doc_id = #{docId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_business_export_doc_item
WHERE doc_id = #{docId}
  AND deleted = 1
  AND tenant_id = #{tenantId}
